// Example code to reproduce the number formatting using toLocaleString

function formatNumber(num) {
  console.log(num.toLocaleString(undefined, {maximumFractionDigits: 1}));
  console.log(num.toLocaleString(undefined, {maximumFractionDigits: 2}));
  console.log(num.toLocaleString(undefined, {maximumFractionDigits: 2, minimumFractionDigits: 2}));
}

// Test the function with different numbers
formatNumber(2445.8311);
formatNumber(2445.00);
formatNumber(2445.000001);
formatNumber(2445.006);
